from typing import List

class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        def can(k: int) -> bool:
            last = [-1] * n
            for t in range(k):
                last[changeIndices[t] - 1] = t

            if any(x == -1 for x in last):
                return False

            need_at_time = [-1] * k
            for i, t in enumerate(last):
                need_at_time[t] = i

            free = 0
            for t in range(k):
                i = need_at_time[t]
                if i == -1:
                    free += 1
                else:
                    if free < nums[i]:
                        return False
                    free -= nums[i]

            return True

        lo, hi = 1, m
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(mid):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1

        return ans
